<?php
 namespace Pterodactyl\Http\Controllers\Dezerx; use Throwable; use Illuminate\Http\Request; use Pterodactyl\Models\Server; use Pterodactyl\Models\Permission; use Illuminate\Http\RedirectResponse; use Illuminate\Support\Facades\Crypt; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Models\Dezerx\DriveBackup; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\Drive\GoogleDrive; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; use Symfony\Component\HttpKernel\Exception\AccessDeniedHttpException; class DriveOAuthController extends Controller { public function connect(Request $request, string $server): RedirectResponse { $model = $this->authorised($request, $server); return redirect()->away(GoogleDrive::consentUrl( route('dezerx.drive.callback'), Crypt::encryptString($model->uuid . '|' . $request->user()->id), )); } public function callback(Request $request): RedirectResponse { try { [$uuid, $userId] = explode('|', Crypt::decryptString((string) $request->query('state', '')), 2); } catch (Throwable) { throw new NotFoundHttpException(); } if ((int) $userId !== (int) $request->user()?->id) { throw new AccessDeniedHttpException('That authorisation was started by a different account.'); } $server = $this->authorised($request, $uuid); $back = "/server/{$server->uuidShort}/backups"; $code = (string) $request->query('code', ''); if ($code === '') { return redirect($back . '?drive=cancelled'); } $tokens = GoogleDrive::exchange($code, route('dezerx.drive.callback')); if ($tokens === null) { return redirect($back . '?drive=failed'); } DriveBackup::query()->updateOrCreate( ['server_id' => $server->id], [ 'user_id' => $request->user()->id, 'refresh_token' => $tokens['refresh_token'], 'account' => (new GoogleDrive($tokens['access_token']))->account(), 'folder_id' => null, 'last_state' => 'idle', 'last_message' => null, ], ); return redirect($back . '?drive=connected'); } private function authorised(Request $request, string $uuid): Server { $server = Server::query() ->where('uuidShort', $uuid) ->orWhere('uuid', $uuid) ->first(); if ($server === null || !Addons::appliesTo(Addons::DRIVE_BACKUPS, $server)) { throw new NotFoundHttpException(); } if (!$request->user()?->can(Permission::ACTION_BACKUP_CREATE, $server)) { throw new AccessDeniedHttpException(); } return $server; } } 